<script setup lang="ts">
import { computed, ref } from 'vue'

const emit = defineEmits<{ openOrders: []; openProducts: [] }>()

const period = ref('30 Hari Terakhir')
const orderFilter = ref('Semua (8)')
const orderSearch = ref('')
const notice = ref('')
let noticeTimer: ReturnType<typeof setTimeout> | undefined

const orders = [
  { id: 'PP-9821', buyer: 'Siti Rahmah', area: 'Cilandak, Jakarta Selatan', date: 'Hari Ini, 09:14 WITA', product: 'Kopi Arabika Flores Bajawa 250g', variant: 'Biji Utuh (Medium Roast) · Qty: 2', courier: 'J&T Reguler', total: 136000, method: 'QRIS PasarPintar (Lunas)', status: 'Perlu Diproses' },
  { id: 'PP-9820', buyer: 'Budi Santoso', area: 'Gubeng, Surabaya', date: 'Hari Ini, 08:32 WITA', product: 'Kopi Arabika Bajawa Bubuk Halus 500g', variant: 'Varian: Bubuk Tubruk · Qty: 1', courier: 'SiCepat Cargo', total: 120000, method: 'VA Mandiri (Lunas)', status: 'Siap Dikirim' },
  { id: 'PP-9818', buyer: 'Anisa Maharani', area: 'Coblong, Bandung', date: 'Kemarin, 21:40 WITA', product: 'Paket Spesial Bajawa Honey Process 200g', variant: 'Varian: Single Origin · Qty: 3', courier: 'JNE OKE', total: 255000, method: 'VA BCA (Lunas)', status: 'Perlu Diproses' },
]

const visibleOrders = computed(() => {
  const query = orderSearch.value.trim().toLocaleLowerCase('id')
  return orders.filter((order) => {
    const matchesQuery = !query || `${order.id} ${order.buyer} ${order.product}`.toLocaleLowerCase('id').includes(query)
    const matchesFilter = orderFilter.value === 'Semua (8)' || (orderFilter.value === 'Perlu Diproses (5)' ? order.status === 'Perlu Diproses' : orderFilter.value === 'Siap Kirim (3)' ? order.status === 'Siap Dikirim' : false)
    return matchesQuery && matchesFilter
  })
})

const salesByPeriod = computed(() => period.value === '7 Hari Terakhir' ? 'Rp 4.210.000' : period.value === '90 Hari Terakhir' ? 'Rp 52.380.000' : 'Rp 18.450.000')
const revenuePoints = computed(() => period.value === '7 Hari Terakhir'
  ? '24,104 78,88 132,96 186,68 240,42 294,58 348,30'
  : period.value === '90 Hari Terakhir'
    ? '24,104 78,79 132,85 186,54 240,46 294,24 348,34'
    : '24,104 78,87 132,95 186,66 240,43 294,58 348,30')
const revenuePath = computed(() => `M ${revenuePoints.value.replace(/ /g, ' L ')}`)
const revenueArea = computed(() => `${revenuePath.value} L 348,124 L 24,124 Z`)

function notify(message: string) {
  notice.value = message
  if (noticeTimer) clearTimeout(noticeTimer)
  noticeTimer = setTimeout(() => { notice.value = '' }, 2600)
}

function downloadReport() {
  const csv = [
    ['Ringkasan', 'Nilai'],
    ['Periode', period.value],
    ['Total Penjualan Bersih', salesByPeriod.value],
    ['Pesanan Baru Bulan Ini', '42'],
    ['Produk Aktif', '28'],
    ['Kepuasan Toko', '4.9 / 5.0'],
  ].map((row) => row.map((value) => `"${value}"`).join(',')).join('\n')
  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }))
  const link = document.createElement('a')
  link.href = url
  link.download = 'ringkasan-kinerja-toko.csv'
  link.click()
  URL.revokeObjectURL(url)
  notify('Laporan ringkasan berhasil diunduh.')
}
</script>

